-- HKSS Decrypted PopTracker pack. Data files are generated by tools/export_poptracker.py.
-- The logic engines (logic_hk.lua, logic_ss.lua, codec.lua) and their data run in
-- logic_worker.lua, on PopTracker's async thread.
ScriptHost:LoadScript("scripts/data_names.lua")
ScriptHost:LoadScript("scripts/logic.lua")

Tracker:AddItems("items/items.json")
Tracker:AddMaps("maps/maps.json")
Tracker:AddLocations("locations/locations.json")
Tracker:AddLayouts("layouts/tracker.json")

if Archipelago then
    ScriptHost:LoadScript("scripts/autotracking.lua")
end
